{"path": "/home/bob/books/The_Unwritten_Future/build_rebrand.py", "content": "#!/usr/bin/env python3
"""
Build 'Tomorrow Is Still Open' with rebranded title, acknowledgment page,
and proper TOC with page numbers.
"""
import re, os, base64, shutil, zipfile
from pathlib import Path
from datetime import datetime

# Files
SOURCE_PATH = Path("/home/bob/.hermes/cache/documents/doc_e21236c1f318_THE_UNWRITTEN_FUTURE_FINAL 3.md")
NEW_SECTION_PATH = Path("/home/bob/.hermes/cache/documents/doc_e4e1cac0981a_1 the_future_after_bob_final_section_20_30_pages.md")
COVER_PATH = Path("/home/bob/books/The_Unwritten_Future/Tomorrow_is_Still_Open_Cover.png")
OUTPUT_DIR = Path("/home/bob/books/The_Unwritten_Future/output")
OUTPUT_DIR.mkdir(exist_ok=True)

BOOK_TITLE = "Tomorrow Is Still Open"
BOOK_SUBTITLE = "A Memoir by Robert Mills"
FILE_PREFIX = "Tomorrow_is_Still_Open"

with open(SOURCE_PATH) as f: manuscript = f.read()
with open(NEW_SECTION_PATH) as f: new_section = f.read()

# ============================================================
# Find epilogue ending and add transition
# ============================================================
last_line_marker = "willingness to touch the outlet anyway"
if last_line_marker in manuscript:
    idx = manuscript.rfind("willingness to touch the outlet anyway")
    end_idx = manuscript.find('\n', idx)
    if end_idx == -1: end_idx = len(manuscript)
    main_body = manuscript[:end_idx].strip()

    transition = """\n---\n\n## The Threshold\n\nBob closes the document. Cindy is calling from downstairs. Dinner is on the table. The evening stretches ahead — ordinary, precious, irreplaceable.\n\nBut a story this size does not end at a dinner table. A life that touched outlets and orbits, that built boats and systems and families, that survived the death of one love and found another — such a life leaves a wake that travels forward. The children of that life will have children. The machines Bob helped build will build machines of their own. The future he could only imagine will become someone else's morning coffee.\n\nThe epilogue is written. But there is one more story to tell. Not a look backward, as epilogues do. A look forward, as Bob always did.\n\nWhat follows is not Bob's memory. It is Bob's imagination — offered to the generations who will inherit what he could only dream of building. These are stories from a shore he will not reach, written for the hands that will hold the tools after his are still.\n\n---\n"""
    manuscript = main_body + "\n\n" + transition + "\n\n" + new_section
    print("✅ Transition added after epilogue ending")
else:
    print("⚠️ Last line marker not found - appending directly")
    manuscript = manuscript.strip() + "\n\n" + transition + "\n\n" + new_section

# ============================================================
# Replace any old title references in manuscript body
# ============================================================
manuscript = manuscript.replace("The Future is Unwritten", BOOK_TITLE)
manuscript = manuscript.replace("The Future is Unwritten", BOOK_TITLE)

# Write updated manuscript
updated_path = OUTPUT_DIR / f"{FILE_PREFIX}_Final.md"
with open(updated_path, "w") as f: f.write(manuscript)
wc = len(manuscript.split())
print(f"✅ Final manuscript saved: {wc:,} words")

# ============================================================
# Build TOC
# ============================================================
toc_entries = []
anchor_ids = []
id_counter = 0

def add_entry(ttype, title, anchor=None):
    global id_counter
    toc_entries.append((ttype, title))
    aid = f"toc-{id_counter}"
    anchor_ids.append(aid)
    id_counter += 1
    return aid

for line in manuscript.split('\n'):
    s = line.strip()
    m1 = re.match(r'^# (Part \w+: .+)$', s)
    if m1: add_entry('part', m1.group(1)); continue
    m2 = re.match(r'^## (Chapter \w+: .+)$', s)
    if m2: add_entry('chapter', m2.group(1)); continue
    if s == '# Epilogue: The Unwritten Future':
        add_entry('epilogue', s[2:].strip()); continue

# Add the new final section
add_entry('final', 'Final Section: The Future After Bob')

# Add subsections
for line in new_section.split('\n'):
    s = line.strip()
    m = re.match(r'^## (.+)$', s)
    if m:
        sub = m.group(1)
        known_subs = ['The Empty Chair', 'The Children of the Assistant Age',
                      'The Day the System Woke Up', 'The Age of Artificial General Organizations',
                      'The New Work', 'The Robots at the Table',
                      'The War of the Small Machines', 'The Quantum Year',
                      'The New Map of Power', 'The Heat and the Water',
                      'The Moon Underfoot', 'The First Child Born Off Earth',
                      'Love in the Augmented World', 'The Letter Bob Could Not Send',
                      'The Last Workshop', 'What Remains']
        if sub in known_subs:
            add_entry('sub', sub)

def esc(text):
    return text.replace('&','&amp;').replace('<','&lt;').replace('>','&gt;')

# ============================================================
# Acknowledgment text
# ============================================================
acknowledgment_text = """<p>I would like to thank my wife, our children, stepchildren, grandchildren, step-grandchildren, and step great-grandchild, along with the friends, colleagues, leaders, coworkers, and employees whose presence and influence helped shape the life remembered in these pages.</p>"""

# ============================================================
# HTML generation with page numbers in TOC
# ============================================================
def inline(text):
    text = re.sub(r'\*\*(.+?)\*\*', r'<strong>\1</strong>', text)
    text = re.sub(r'\*(.+?)\*', r'<em>\1</em>', text)
    return text

def md_to_html(text):
    lines = text.split('\n')
    result = []
    in_ul = False
    in_quote = False

    for raw in lines:
        s = raw.strip()

        if not s:
            if in_ul: result.append('</ul>'); in_ul = False
            if in_quote: result.append('</blockquote>'); in_quote = False
            result.append(''); continue

        if s in ('---', '___', '***'):
            if in_ul: result.append('</ul>'); in_ul = False
            if in_quote: result.append('</blockquote>'); in_quote = False
            result.append('<hr>'); continue

        if re.match(r'^# Part \w+:', s):
            if in_ul: result.append('</ul>'); in_ul = False
            if in_quote: result.append('</blockquote>'); in_quote = False
            result.append(f'<h2 class="part-title" id="toc-anchor">{esc(s[2:].strip())}</h2>'); continue

        if re.match(r'^## Chapter \w+:', s):
            if in_ul: result.append('</ul>'); in_ul = False
            if in_quote: result.append('</blockquote>'); in_quote = False
            result.append(f'<h3>{esc(s[3:].strip())}</h3>'); continue

        if s.startswith('# Epilogue'):
            if in_ul: result.append('</ul>'); in_ul = False
            if in_quote: result.append('</blockquote>'); in_quote = False
            result.append(f'<h2 class="epilogue-title" id="toc-anchor">{esc(s[2:].strip())}</h2>'); continue

        if s.startswith('# Final Section'):
            if in_ul: result.append('</ul>'); in_ul = False
            if in_quote: result.append('</blockquote>'); in_quote = False
            result.append(f'<h2 class="final-section-title" id="toc-anchor">{esc(s[2:].strip())}</h2>'); continue

        if s.startswith('## '):
            if in_ul: result.append('</ul>'); in_ul = False
            if in_quote: result.append('</blockquote>'); in_quote = False
            result.append(f'<h4>{esc(s[3:].strip())}</h4>'); continue

        if s.startswith('### '):
            if in_ul: result.append('</ul>'); in_ul = False
            if in_quote: result.append('</blockquote>'); in_quote = False
            result.append(f'<h5>{esc(s[4:].strip())}</h5>'); continue

        if s.startswith('### Transition'):
            if in_ul: result.append('</ul>'); in_ul = False
            if in_quote: result.append('</blockquote>'); in_quote = False
            result.append(f'<hr class="transition">'); continue

        if s.startswith('- ') or s.startswith('* '):
            if in_quote: result.append('</blockquote>'); in_quote = False
            if not in_ul: result.append('<ul>'); in_ul = True
            result.append(f'<li>{inline(s[2:])}</li>'); continue

        if s.startswith('>'):
            if in_ul: result.append('</ul>'); in_ul = False
            if not in_quote: result.append('<blockquote>'); in_quote = True
            result.append(f'<p>{inline(s[1:].strip())}</p>'); continue

        if re.match(r'^\*\*.+\*\*$', s) and len(s) < 80:
            if in_ul: result.append('</ul>'); in_ul = False
            if in_quote: result.append('</blockquote>'); in_quote = False
            result.append(f'<p class="section-heading">{inline(s)}</p>'); continue

        if in_ul: result.append('</ul>'); in_ul = False
        if in_quote: result.append('</blockquote>'); in_quote = False
        result.append(f'<p>{inline(s)}</p>')

    if in_ul: result.append('</ul>')
    if in_quote: result.append('</blockquote>')
    return '\n'.join(result)

# Encode cover
cover_b64 = ""
if COVER_PATH.exists():
    with open(COVER_PATH, "rb") as f: cover_b64 = base64.b64encode(f.read()).decode()

# Build TOC HTML with leader dots and page numbers
# Using target-counter for WeasyPrint dynamic page numbers
toc_html_lines = ['<div class="toc-page"><h2>Contents</h2><ul>']
for idx, (ttype, title) in enumerate(toc_entries):
    anchor_id = anchor_ids[idx]
    css_class = f"toc-{ttype}"
    entry_html = f'<li class="{css_class}"><a href="#{anchor_id}">{esc(title)}</a></li>'
    toc_html_lines.append(entry_html)
toc_html_lines.append('</ul></div>')

# Convert body
body_html = md_to_html(manuscript)

# The acknowledgment page goes after copyright
acknowledgment_html = f"""<div class="acknowledgments-page">
    <h2>Acknowledgments</h2>
    {acknowledgment_text}
</div>"""

# Build full HTML - proper book structure
html = f'''<!DOCTYPE html><html lang="en">
<head>
<meta charset="UTF-8">
<title>{BOOK_TITLE}</title>
<style>
@page {{ size: 6in 9in; margin: 0.9in 0.85in;
    @top-center {{ content: "{BOOK_TITLE}"; font-family: 'Times New Roman', Times, serif; font-size: 8pt; color: #999; }}
    @bottom-center {{ content: counter(page); font-family: 'Times New Roman', Times, serif; font-size: 9pt; color: #666; }}
}}
@page:first {{ @top-center {{ content: none; }} @bottom-center {{ content: none; }} }}
@page:cover {{ @top-center {{ content: none; }} @bottom-center {{ content: none; }} }}
* {{ box-sizing: border-box; }}
body {{ font-family: 'Times New Roman', Times, serif; font-size: 11pt; line-height: 1.6; color: #000; margin: 0; padding: 0; }}

.cover-page {{ page-break-after: always; text-align: center; padding: 40px; }}
.cover-page img {{ max-width: 100%; height: auto; }}

.title-page {{ page-break-after: always; text-align: center; padding: 120px 40px; }}
.title-page .title {{ font-size: 28pt; font-weight: bold; margin-bottom: 15px; }}
.title-page .subtitle {{ font-size: 16pt; color: #555; font-style: italic; }}

.copyright-page {{ page-break-after: always; font-size: 9pt; color: #444; padding-top: 50px; }}

.acknowledgments-page {{ page-break-after: always; font-size: 10pt; color: #333; padding-top: 60px; text-align: center; }}
.acknowledgments-page h2 {{ font-size: 14pt; font-weight: bold; margin-bottom: 20px; border-bottom: 1px solid #ccc; padding-bottom: 8px; display: inline-block; }}
.acknowledgments-page p {{ margin: 15px auto; max-width: 450px; text-align: justify; text-indent: 1.5em; line-height: 1.7; }}

.toc-page {{ page-break-after: always; }}
.toc-page h2 {{ font-size: 18pt; font-weight: bold; text-align: center; margin-bottom: 28px; border-bottom: 2px solid #000; padding-bottom: 10px; }}
.toc-page ul {{ list-style: none; padding: 0; counter-reset: toc-page-num; }}
.toc-page li {{ margin: 4px 0; padding: 3px 0; font-size: 11pt; position: relative; }}
.toc-page li a {{ color: #000; text-decoration: none; display: inline-block; background: #fff; position: relative; z-index: 1; padding-right: 5px; }}
.toc-page li.toc-part {{ font-weight: bold; font-size: 11pt; border-bottom: 1px solid #000; padding-top: 8px; }}
.toc-page li.toc-chapter {{ padding-left: 15px; font-size: 10pt; border-bottom: 1px dotted #ccc; }}
.toc-page li.toc-epilogue {{ font-weight: bold; padding-top: 8px; border-bottom: 1px solid #000; }}
.toc-page li.toc-final {{ font-weight: bold; padding-top: 8px; border-bottom: 1px solid #000; }}
.toc-page li.toc-sub {{ padding-left: 25px; font-size: 9.5pt; font-style: italic; border-bottom: 1px dotted #ddd; }}
.toc-page li a::after {{ content: target-counter(attr(href), page); float: right; background: #fff; position: relative; z-index: 1; padding-left: 5px; }}

.chapter-content {{ }}
.chapter-content h2.part-title {{ font-size: 18pt; font-weight: bold; text-align: center; margin: 30px 0 15px; page-break-before: always; text-transform: uppercase; letter-spacing: 2px; }}
.chapter-content h3 {{ font-size: 14pt; font-weight: bold; margin: 20px 0 10px; }}
.chapter-content h4 {{ font-size: 12pt; font-weight: bold; font-style: italic; margin: 16px 0 8px; }}
.chapter-content h5 {{ font-size: 11pt; font-weight: bold; margin: 12px 0 6px; }}
.chapter-content p {{ margin: 6px 0; text-align: justify; line-height: 1.6; text-indent: 1.5em; }}
.chapter-content ul {{ margin: 6px 0 6px 2em; }}
.chapter-content li {{ margin: 3px 0; }}
.chapter-content blockquote {{ margin: 12px 30px; padding: 10px 20px; border-left: 3px solid #ccc; font-style: italic; color: #444; }}
.chapter-content blockquote p {{ text-indent: 0; }}
.chapter-content p.section-heading {{ text-indent: 0; font-weight: bold; margin-top: 14px; }}
.chapter-content hr {{ border: none; border-top: 1px solid #ccc; margin: 20px 40px; }}
.chapter-content hr.transition {{ margin: 25px 60px; border-top: 1px solid #999; }}
.chapter-content h2.epilogue-title {{ font-size: 18pt; font-weight: bold; text-align: center; margin: 30px 0 20px; page-break-before: always; }}
.chapter-content h2.final-section-title {{ font-size: 18pt; font-weight: bold; text-align: center; margin: 30px 0 20px; page-break-before: always; border-bottom: 2px solid #8b4513; padding-bottom: 10px; }}

.back-cover {{ page-break-before: always; background: #1a1a2e; color: #fff; text-align: center; padding: 70px 40px; min-height: 650px; }}
.back-cover h2 {{ font-size: 22pt; margin-bottom: 8px; }}
.back-cover .back-subtitle {{ font-size: 13pt; font-style: italic; color: #aaa; margin-bottom: 35px; }}
.back-cover .review {{ font-style: italic; font-size: 11pt; margin: 25px 20px; color: #ddd; }}
.back-cover hr {{ border: none; border-top: 1px solid #444; margin: 25px 50px; }}
.back-cover .publisher {{ font-size: 9pt; color: #777; margin-top: 50px; }}
</style>
</head><body>

<div class="cover-page">{'' if not cover_b64 else f'<img src="data:image/png;base64,{cover_b64}" alt="Cover">'}
</div>

<div class="title-page">
    <h1 class="title">{BOOK_TITLE}</h1>
    <p class="subtitle">{BOOK_SUBTITLE}</p>
</div>

<div class="copyright-page">
    <p><strong>Copyright &copy; 2025 by Robert Mills</strong></p>
    <p>All rights reserved. No part of this publication may be reproduced, distributed, or transmitted in any form or by any means without the prior written permission of the publisher.</p>
    <p><strong>First Edition: 2026</strong></p>
</div>

{acknowledgment_html}

{''.join(toc_html_lines)}

<div class="chapter-content">
{body_html}
</div>

<div class="back-cover">
    <h2>{BOOK_TITLE}</h2>
    <p class="back-subtitle">A Memoir</p>
    <div class="review">"A remarkable journey from a Michigan kitchen to the frontiers of technology and the human heart."</div>
    <hr>
    <p class="publisher">Mills Publishing</p>
</div>

</body></html>'''

# Add anchor IDs to TOC target headers in the body_html portion
# We need to find each ## Part, ## Epilogue, ## Final Section header and add the corresponding anchor ID
for idx, (ttype, title) in enumerate(toc_entries):
    anchor_id = anchor_ids[idx]
    # Find the header in the body and add id
    safe_title = esc(title)

    if ttype == 'part':
        old = f'<h2 class="part-title">{safe_title}</h2>'
        new = f'<h2 class="part-title" id="{anchor_id}">{safe_title}</h2>'
        html = html.replace(old, new, 1)
    elif ttype == 'epilogue':
        old = f'<h2 class="epilogue-title">{safe_title}</h2>'
        new = f'<h2 class="epilogue-title" id="{anchor_id}">{safe_title}</h2>'
        html = html.replace(old, new, 1)
    elif ttype == 'final':
        old = f'<h2 class="final-section-title">{safe_title}</h2>'
        new = f'<h2 class="final-section-title" id="{anchor_id}">{safe_title}</h2>'
        html = html.replace(old, new, 1)
    elif ttype in ('chapter', 'sub'):
        # For chapter headers (<h3>) and sub headers (<h4>)
        tag = 'h3' if ttype == 'chapter' else 'h4'
        old = f'<{tag}>{safe_title}</{tag}>'
        new = f'<{tag} id="{anchor_id}">{safe_title}</{tag}>'
        html = html.replace(old, new, 1)

# But part-title anchors might already have id="toc-anchor" from our md_to_html function
# Let's fix that
html = html.replace('id="toc-anchor"', '', 10)  # Remove placeholder

# Re-add proper anchors
for idx, (ttype, title) in enumerate(toc_entries):
    anchor_id = anchor_ids[idx]
    safe_title = esc(title)

    if ttype == 'part':
        html = html.replace(f'<h2 class="part-title">{safe_title}</h2>', f'<h2 class="part-title" id="{anchor_id}">{safe_title}</h2>', 1)
    elif ttype == 'epilogue':
        html = html.replace(f'<h2 class="epilogue-title">{safe_title}</h2>', f'<h2 class="epilogue-title" id="{anchor_id}">{safe_title}</h2>', 1)
    elif ttype == 'final':
        html = html.replace(f'<h2 class="final-section-title">{safe_title}</h2>', f'<h2 class="final-section-title" id="{anchor_id}">{safe_title}</h2>', 1)
    elif ttype == 'chapter':
        html = html.replace(f'<h3>{safe_title}</h3>', f'<h3 id="{anchor_id}">{safe_title}</h3>', 1)
    elif ttype == 'sub':
        html = html.replace(f'<h4>{safe_title}</h4>', f'<h4 id="{anchor_id}">{safe_title}</h4>', 1)

html_path = OUTPUT_DIR / f"{FILE_PREFIX}.html"
with open(html_path, "w") as f: f.write(html)
hs = os.path.getsize(html_path)
print(f"✅ HTML: {html_path} ({hs:,} bytes)")
print(f"   TOC entries: {len(toc_entries)}")

# ============================================================
# PDF generation
# ============================================================
from weasyprint import HTML as WHTML
pdf_path = OUTPUT_DIR / f"{FILE_PREFIX}.pdf"
print("Generating PDF...")
try:
    WHTML(string=html).write_pdf(str(pdf_path))
    print(f"✅ PDF: {pdf_path} ({os.path.getsize(pdf_path):,} bytes)")
except Exception as e:
    print(f"❌ PDF failed: {e}")

# ============================================================
# EPUB generation
# ============================================================
epub_dir = OUTPUT_DIR / "epub_temp"
epub_dir.mkdir(exist_ok=True)
(epub_dir / "META-INF").mkdir(exist_ok=True)
(epub_dir / "OEBPS").mkdir(exist_ok=True)

with open(epub_dir / "mimetype", "w") as f: f.write("application/epub+zip")
with open(epub_dir / "META-INF" / "container.xml", "w") as f:
