manifest.append('<item id="copyright" href="copyright.xhtml" media-type="application/xhtml+xml"/>')
spine.append('<itemref idref="copyright"/>')

# Acknowledgments page for EPUB
ack_epub = f'<?xml version="1.0" encoding="UTF-8"?>\n<!DOCTYPE html><html xmlns="http://www.w3.org/1999/xhtml"><head><title>Acknowledgments</title><style>body{{font-family:"Times New Roman",Times,serif;font-size:11pt;text-align:center;padding:40px 30px;}}h2{{font-size:14pt;font-weight:bold;margin-bottom:20px;}}p{{margin:15px auto;max-width:450px;text-align:justify;text-indent:1.5em;line-height:1.7;}}</style></head><body><h2>Acknowledgments</h2>{acknowledgment_text}</body></html>'
