manifest.append('<item id="acknowledgments" href="acknowledgments.xhtml" media-type="application/xhtml+xml"/>')
spine.append('<itemref idref="acknowledgments"/>')

epub_css = 'body{font-family:"Times New Roman",Times,serif;font-size:11pt;line-height:1.6;margin:20px;}h2{font-size:18pt;font-weight:bold;text-align:center;margin-bottom:15px;}h3{font-size:14pt;font-weight:bold;margin:18px 0 8px;}h4{font-size:12pt;font-weight:bold;font-style:italic;margin:12px 0 6px;}p{margin:5px 0;text-align:justify;text-indent:1.5em;line-height:1.6;}ul{margin:5px 0 5px 2em;}li{margin:2px 0;}blockquote{margin:10px 20px;padding:8px 15px;border-left:3px solid #ccc;font-style:italic;}hr{margin:15px 30px;border:none;border-top:1px solid #ccc;}'

nav_items = []
for ttype, title in toc_entries:
    nav_items.append(f'<li>{esc(title)}</li>')

body_epub = md_to_html(manuscript)
content_xhtml = f'<?xml version="1.0" encoding="UTF-8"?>\n<!DOCTYPE html><html xmlns="http://www.w3.org/1999/xhtml"><head><title>{BOOK_TITLE}</title><style>{epub_css}</style></head><body>{body_epub}</body></html>'
with open(epub_dir / "OEBPS" / "content.xhtml", "w") as f: f.write(content_xhtml)
manifest.append('<item id="content" href="content.xhtml" media-type="application/xhtml+xml"/>')
spine.append('<itemref idref="content"/>')

nav_xhtml = f'<?xml version="1.0" encoding="UTF-8"?>\n<!DOCTYPE html><html xmlns="http://www.w3.org/1999/xhtml" xmlns:epub="http://www.idpf.org/2007/ops"><head><title>Nav</title></head><body><nav epub:type="toc"><h2>Contents</h2><ol>{"".join(nav_items)}</ol></nav></body></html>'
with open(epub_dir / "OEBPS" / "nav.xhtml", "w") as f: f.write(nav_xhtml)
manifest.append('<item id="nav" href="nav.xhtml" media-type="application/xhtml+xml" properties="nav"/>')

ml = '\n'.join('    ' + m for m in manifest)
sl = '\n'.join('    ' + s for s in spine)
opf = f'''<?xml version="1.0" encoding="UTF-8"?>
<package xmlns="http://www.idpf.org/2007/opf" version="3.0" unique-identifier="book-id">
  <metadata xmlns:dc="http://purl.org/dc/elements/1.1/">
