    <dc:date>{datetime.now().strftime('%Y-%m-%d')}</dc:date>
    <dc:publisher>Mills Publishing</dc:publisher>
    <meta property="dcterms:modified">{datetime.now().strftime('%Y-%m-%dT%H:%M:%SZ')}</meta>
  </metadata>
  <manifest>
{ml}
  </manifest>
  <spine>
{sl}
  </spine>
</package>'''
with open(epub_dir / "OEBPS" / "content.opf", "w") as f: f.write(opf)

epub_path = OUTPUT_DIR / f"{FILE_PREFIX}.epub"
with zipfile.ZipFile(epub_path, 'w', zipfile.ZIP_DEFLATED) as zf:
    for root, dirs, files in os.walk(epub_dir):
        for f in files:
            zf.write(os.path.join(root, f), os.path.relpath(os.path.join(root, f), epub_dir))
shutil.rmtree(epub_dir)
print(f"✅ EPUB: {epub_path} ({os.path.getsize(epub_path):,} bytes)")

print(f"\n✅✅✅ ALL FILES GENERATED ✅✅✅")
print(f"  MD:   {updated_path}")
print(f"  HTML: {html_path}")
print(f"  PDF:  {pdf_path}")
print(f"  EPUB: {epub_path}")
"}

